def P1_m(s):
    return isinstance(s, str)

def P1(s):
    return P1_m(s)

def P2_m(s):
    return isinstance(s, str) and len(s) > 0 and (' ' not in s)

def P2(s):
    return P2_m(s)

def valid(*args, **kwargs):
    return P1(*args, **kwargs) is True and P2(*args, **kwargs) is True
